{
  "name": "Senior Document Controller",
  "description": "Manages document lifecycle with approval rights"
}

{
  "messages": [
    {"role": "system", "content": "You are a quality management expert."},
    {"role": "user", "content": "What are the key elements of a CAPA?"}
  ],
  "provider": "openai",
  "model": "gpt-4",
  "temperature": 0.7,
  "max_tokens": 1000
}

{
  "name": "root-cause-analysis",
  "description": "Analyze root cause of quality issues",
  "category": "quality",
  "template": "Analyze the following issue using 5-Why methodology:\n\nIssue: {{issue}}\nContext: {{context}}\n\nProvide a detailed root cause analysis.",
  "variables": ["issue", "context"],
  "settings": {
    "provider": "openai",
    "model": "gpt-4",
    "temperature": 0.3,
    "max_tokens": 2000
  }
}

{
  "variables": {
    "issue": "Batch 12345 failed dissolution testing",
    "context": "Manufacturing date: Dec 25, Equipment: Tablet Press #3"
  }
}

