  "variables": {
    "issue": "Batch 12345 failed dissolution testing",
    "context": "Manufacturing date: Dec 25, Equipment: Tablet Press #3"
  }
}

{
  "name": "External Audit System",
  "description": "Notify external audit system of all events",
  "url": "https://audit-system.example.com/webhook",
  "events": ["audit.*", "capa.created", "change.approved"],
  "authType": "bearer",
  "authConfig": {"token": "secret-token"},
  "headers": {"X-Custom-Header": "QAssure"}
}
